'use strict';
const coolingSensors={
 'Supply sensor TT-01':{label:'Supply air',value:'18.2',unit:'°C',status:'operational',limit:'18–20 °C',note:'Supply air is within its target range.',rows:[['Sensor ID','TT-01'],['Location','Supply outlet'],['Airflow','42,000 m³/h']]},
 'Supply fan VFD-01':{label:'Supply fan',value:'1,450',unit:'RPM',status:'operational',limit:'1,200–1,600 RPM',note:'Fan speed is within the demonstration operating band.',rows:[['Drive frequency','48.3 Hz'],['Motor load','72 %'],['Vibration','2.1 mm/s']]},
 'Filter differential DP-01':{label:'Filter differential pressure',value:'125',unit:'Pa',status:'operational',limit:'Below 200 Pa',note:'Filter differential pressure is below the replacement advisory threshold.',rows:[['Sensor ID','DP-01'],['Filter stage','Pleated filter bank'],['Advisory threshold','200 Pa']]},
 'Return sensor TT-02':{label:'Return air',value:'29.4',unit:'°C',status:'critical',limit:'Below 28 °C',note:'Return air is above the configured 28 °C threshold. Verify sensor reading, calibration, placement, and airflow.',rows:[['Sensor ID','TT-02'],['Location','Return duct'],['Deviation','+1.4 °C above limit']]},
 'Chilled water TT-03':{label:'Chilled water',value:'7.0',unit:'°C',status:'operational',limit:'6–8 °C',note:'Chilled-water supply is within its demonstration operating range.',rows:[['Sensor ID','TT-03'],['Circuit pressure','3.2 bar'],['Valve position','64 %']]}
};
function coolingTrend(){
 const ys=v=>128-(v-16)/16*108;
 const line=(base,phase)=>Array.from({length:37},(_,i)=>`${43+i*9.45},${ys(base+Math.sin(i*1.4+phase)*.21+Math.cos(i*.57)*.12).toFixed(2)}`).join(' ');
 return `<div class="cooling-trend"><svg viewBox="0 0 470 160" role="img" aria-label="Illustrative supply air trend around 18.2 degrees and return air trend around 29.4 degrees from 14:00 to 18:00">${[16,18,20,22,24,26,28,30,32].map(v=>`<line x1="43" x2="385" y1="${ys(v)}" y2="${ys(v)}" stroke="#536774" stroke-opacity=".5" stroke-width=".7"/><text x="7" y="${ys(v)+3}" fill="#b9cbd7" font-size="9">${v} °C</text>`).join('')}${Array.from({length:9},(_,i)=>`<line x1="${43+i*42.5}" x2="${43+i*42.5}" y1="20" y2="128" stroke="#536774" stroke-opacity=".25"/><text x="${43+i*42.5}" y="148" fill="#b9cbd7" font-size="8" text-anchor="middle">${14+Math.floor(i/2)}:${i%2?'30':'00'}</text>`).join('')}<polyline points="${line(29.4,0)}" stroke="#ff727a" stroke-width="1.8" fill="none"/><polyline points="${line(18.2,2)}" stroke="#64e9ff" stroke-width="1.8" fill="none"/><circle cx="408" cy="53" r="3" fill="#ff727a"/><text x="418" y="56" font-size="9" fill="#e5edf3">Return</text><text x="418" y="73" font-size="13" fill="#fff">29.4 °C</text><circle cx="408" cy="95" r="3" fill="#64e9ff"/><text x="418" y="98" font-size="9" fill="#e5edf3">Supply</text><text x="418" y="115" font-size="13" fill="#fff">18.2 °C</text></svg></div>`;
}
function coolingTag(asset,cls,label,value){return `<button class="cooling-sensor ${cls}" data-equipment="${asset}" aria-label="Inspect ${label}, ${value}"><span>${label}</span><strong>${value}</strong>${cls==='return'?'<i aria-hidden="true">!</i>':''}</button>`}
mechanical=function(){
 return `<div class="cooling-page"><div class="kpi-grid">${kpi('Cooling demand','1.84','MW','● Stable','current building load',2,C.blue)}${kpi('Supply air temperature','18.2','°C','● Within range','target: 18–20 °C',0)}${kpi('Cooling COP','5.30','','↑ 0.2','vs. yesterday',3)}${kpi('AHU-03 return air','29.4','°C','↑ Above limit','threshold: 28 °C',1,C.red)}</div><section class="cooling-hero" aria-label="AHU-03 interactive air handling unit"><img class="cooling-plant-image" src="assets/ahu-03.png" alt="Cutaway air handling unit with fan, filter bank, cooling coil and chilled water piping inside a mechanical plant room"><div class="cooling-hero-shade"></div><div class="cooling-hero-heading"><h2>AHU-03 · Air handling unit</h2><p>Select a sensor or component to inspect its readings.</p></div><div class="cooling-live"><i></i> SIMULATED ASSET VIEW</div><button class="cooling-alarm" data-equipment="Return sensor TT-02">1 critical event</button><svg class="cooling-overlay" viewBox="0 0 1000 350" preserveAspectRatio="none" aria-hidden="true"><defs><linearGradient id="cold-stream"><stop stop-color="#4ce8f1" stop-opacity="0"/><stop offset=".6" stop-color="#57edff" stop-opacity=".8"/><stop offset="1" stop-color="#5ce5ef" stop-opacity="0"/></linearGradient><linearGradient id="warm-stream"><stop stop-color="#e7a160" stop-opacity="0"/><stop offset=".5" stop-color="#f7b268" stop-opacity=".7"/><stop offset="1" stop-color="#f7a25b" stop-opacity="0"/></linearGradient></defs>${[0,1,2,3].map(i=>`<path class="cooling-airflow cold" d="M252 ${196+i*8}C195 ${155+i*12} 140 ${242-i*7} 35 ${196+i*9}" stroke="url(#cold-stream)"/><path class="cooling-airflow warm" d="M985 ${194+i*8}C940 ${174+i*11} 880 ${218-i*5} 802 ${195+i*9}" stroke="url(#warm-stream)"/>`).join('')}<g class="cooling-leaders"><path d="M159 107 140 191" class="cold"/><path d="M490 89 450 203"/><path d="M285 85 270 175"/><path d="M865 96 860 182" class="hot"/><path d="M822 284 730 277" class="cold"/><circle cx="140" cy="191" r="2.6" class="cold"/><circle cx="450" cy="203" r="2.6"/><circle cx="270" cy="175" r="2.6"/><circle cx="860" cy="182" r="2.6" class="hot"/><circle cx="730" cy="277" r="2.6" class="cold"/></g></svg>${coolingTag('Supply sensor TT-01','supply','Supply','18.2 °C')}${coolingTag('Supply fan VFD-01','fan','Fan','1,450 RPM')}${coolingTag('Filter differential DP-01','filter','Filter ΔP','125 Pa')}${coolingTag('Return sensor TT-02','return','Return','29.4 °C')}${coolingTag('Chilled water TT-03','water','Chilled water','7.0 °C')}<div class="cooling-unit-label">AHU-03</div></section><div class="cooling-bottom">${panel('Cooling performance','Supply and return trend · illustrative',coolingTrend())}${panel('Cooling capacity','Load against installed capacity',`<div class="cooling-capacity">${donut(57.5,'Utilization',C.mint)}<div><small>Available</small><strong>1.36 <span>MW</span></strong><p>Installed 3.20 MW</p></div></div>`)}${panel('Maintenance recommendation','Illustrative rule-based advisory',`<button class="cooling-advisory" data-equipment="Return sensor TT-02"><span class="cooling-warning">⚠</span><span><strong>Inspect AHU-03 return sensor</strong><p>Return air temperature (29.4 °C) is above the 28 °C threshold.<br>Verify sensor reading, calibration, and placement.</p></span></button>`)}</div></div>`;
};
const coolingOriginalInspector=equipmentDrawer;
equipmentDrawer=function(name){
 const s=coolingSensors[name];
 if(!s){coolingOriginalInspector(name);return}
 openDrawer(`<div class="eyebrow">AHU-03 / SENSOR INSPECTOR</div><h2>${esc(s.label)}</h2><p>${esc(currentSite().name)} / ${state.building||'DC-01'} · Simulated telemetry</p>${status(s.status)}<div class="cooling-inspector-value ${s.status==='critical'?'negative':''}">${s.value}<small>${s.unit}</small></div><div class="detail-list"><p>Asset<strong>${esc(name)}</strong></p><p>Operating limit<strong>${s.limit}</strong></p>${s.rows.map(([k,v])=>`<p>${k}<strong>${v}</strong></p>`).join('')}<p>Telemetry source<strong>Local demonstration</strong></p></div><h3>Operating note</h3><p>${s.note}</p><button class="button primary" data-action="new-work">Create inspection work order</button>`);
};
render();
